package model

import (
	"errors"
	"time"

	"gorm.io/gorm"
)

const (
	MessageTypeText   = "text"
	MessageTypeImage  = "image"
	MessageTypeFile   = "file"
	MessageTypeVoice  = "voice"
	MessageTypeRecall = "recall"
	MessageTypeSystem = "system"

	MessageStatusNormal   = "normal"
	MessageStatusRecalled = "recalled"
)

// ErrMissingSnowflakeID guards against inserting a Message without a server-assigned Snowflake ID.
var ErrMissingSnowflakeID = errors.New("message id must be assigned by snowflake before insert")

// Message maps the `messages` table.
// ID MUST be generated by the server-side Snowflake generator and is never auto-incremented by MySQL.
type Message struct {
	ID             uint64       `gorm:"column:id;type:bigint unsigned;primaryKey;autoIncrement:false" json:"msg_id,string"`
	ConversationID uint64       `gorm:"column:conversation_id;type:bigint unsigned;not null;uniqueIndex:uk_msg_conv_seq,priority:1;index:idx_msg_conv_created,priority:1" json:"conversation_id,string"`
	Seq            uint64       `gorm:"column:seq;type:bigint unsigned;not null;uniqueIndex:uk_msg_conv_seq,priority:2" json:"seq,string"`
	SenderID       uint64       `gorm:"column:sender_id;type:bigint unsigned;not null;uniqueIndex:uk_msg_sender_client,priority:1;index:idx_msg_sender_created,priority:1" json:"sender_id,string"`
	ClientMsgID    string       `gorm:"column:client_msg_id;type:varchar(64);not null;uniqueIndex:uk_msg_sender_client,priority:2" json:"client_msg_id"`
	MsgType        string       `gorm:"column:msg_type;type:enum('text','image','file','voice','recall','system');not null" json:"msg_type"`
	Content        string       `gorm:"column:content;type:text;not null" json:"content"`
	Extra          NullableJSON `gorm:"column:extra;type:json;default:null" json:"extra"`
	Status         string       `gorm:"column:status;type:enum('normal','recalled');not null;default:'normal'" json:"status"`
	RecalledAt     *time.Time   `gorm:"column:recalled_at;type:datetime(3);default:null" json:"recalled_at"`
	CreatedAt      time.Time    `gorm:"column:created_at;type:datetime(3);not null;autoCreateTime;index:idx_msg_conv_created,priority:2,sort:desc;index:idx_msg_sender_created,priority:2,sort:desc" json:"created_at"`
}

// TableName returns the MySQL table name.
func (Message) TableName() string {
	return "messages"
}

// BeforeCreate ensures messages.id never falls back to database auto-increment.
func (m *Message) BeforeCreate(_ *gorm.DB) error {
	if m.ID == 0 {
		return ErrMissingSnowflakeID
	}
	return nil
}
